        boolean[] vowel = new boolean[128];
        for (char c : "aeiouAEIOU".toCharArray()) {
            vowel[c] = true;
        }

        char[] chars = s.toCharArray();
        int left = 0;
        int right = chars.length - 1;
        while (left < right) {
            while (left < right && !vowel[chars[left]]) {
                left++;
